insert into public.issue_updates (issue_id, role, author_name, text, created_at) values
  ('PP-2402', 'partner', 'West Side District', 'These lamps belong to NYC DOT, so we filed a 311 request (SR 311-21847390). We will follow up with DOT and raise it at the next District Service Cabinet meeting if there is no answer.', private.seed_ago(12, 10)),
  ('PP-2402', 'resident', 'Priya S.', 'Walked my kid home this way last night. It''s pitch black between the two posts.', private.seed_ago(2, 11)),
  ('PP-2419', 'partner', 'West Side District', 'The owner of the corner building is responsible for this stretch of sidewalk. Their manager has coned off the paver and scheduled the reset for the week of Oct 19.', private.seed_ago(4, 10)),
  ('PP-2440', 'resident', 'Marcus T.', 'Started at 6:10 this morning again. Three blowers at once.', private.seed_ago(1, 10)),
  ('PP-2371', 'resident', 'Dana K.', 'Thanks for getting the bench by the fountain fixed so fast. First time I''ve seen a report actually go somewhere.', private.seed_ago(25, 10));
