-- Generated by scripts/generate-seed.ts from src/data/sampleData.ts and src/data/demoDistrict.ts.
-- Don't edit by hand: change the sample data and run `npm run db:seed-sql`.
--
-- Sample data for the fictional West Side District. Fine for local and staging, never for production.
-- Dates are relative to the day it runs (2026-10-14 in the sample = today in New York).
-- Meant for an empty database: `supabase db reset` locally, or once on a new staging project:
--   psql "$DB_URL" --single-transaction -v ON_ERROR_STOP=1 -f supabase/seed.sql

-- Don't send a Realtime ping for every seeded row.
set pp.seeding = 'on';

-- Seed-only helpers, dropped at the end.
-- Noon in New York, `days` days ago (plus `minutes`), never in the future.
create function private.seed_ago(days integer, minutes integer default 0)
returns timestamptz
language sql
as $$
  select least(
    now(),
    ((((now() at time zone 'America/New_York')::date - days) + time '12:00') + make_interval(mins => minutes))
      at time zone 'America/New_York'
  );
$$;

-- `n` timestamps spread from `from_days` ago to `to_days` ago.
create function private.seed_spread(n integer, from_days integer, to_days integer)
returns setof timestamptz
language sql
as $$
  select private.seed_ago(from_days - (g * (from_days - to_days + 1)) / n, (g * 37) % 600)
  from generate_series(0, n - 1) g;
$$;

-- The inserts run inside one block because `supabase db reset` prepares every top-level
-- statement before running any, and the helpers above don't exist yet at that point.
do $seed$
begin

if exists (select 1 from public.districts where id = 'west-side-demo') then
  raise exception 'The sample district west-side-demo is already loaded.';
end if;

values (
  'west-side-demo', 'West Side District', 'West Chelsea', 40.742778, -74.00551, 16,
  '{"type":"Polygon","coordinates":[[[-74.0026,40.738369999999996],[-73.9986,40.74417],[-74.0076,40.74897],[-74.0116,40.74317],[-74.0026,40.738369999999996]]]}'::jsonb,
  array['lighting', 'seating', 'accessibility', 'litter', 'noise', 'other'],
  array['District office staff'],
  '{"cityNoReplyDays":10,"quietDays":14}'::jsonb,
  'office@westside.example'
);


-- Duplicate reports already merged (their votes and follows now count on the issue they went into).




-- Anonymous votes, follows and fix confirmations behind the sample counts.

-- The demo's sample analytics (src/data/demoEvents.ts), so the dashboard and Reports have figures to show.


end;
$seed$;

drop function private.seed_spread(integer, integer, integer);
drop function private.seed_ago(integer, integer);
reset pp.seeding;
